const PREVIEW = window.BUGCASP_PREVIEW === true;
const $ = selector => document.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const raw = value => `<span translate="no">${esc(value)}</span>`;
const currencyOf = item => item.currency || (PREVIEW ? 'AZN' : 'USD');
const money = (amount, currency='AZN') => num(amount)+' '+(currency==='AZN'?'₼':'USD');
function totalsText(totals){return Object.entries(totals).filter(([,v])=>v).map(([c,v])=>money(v,c)).join(' · ')||money(0);}
function paidTotals(rows){const totals={};for(const r of rows.filter(r=>r.payout_paid)){const c=currencyOf(r);totals[c]=(totals[c]||0)+r.cash_awarded;}return totalsText(totals);}
function highestRewards(rows){const totals={};for(const p of rows.filter(p=>p.bounty_type==='cash')){const c=currencyOf(p);totals[c]=Math.max(totals[c]||0,p.reward_critical);}return totalsText(totals);}
