function renderPrograms(){
  $('#main').innerHTML=heading('ARAŞDIR · HESABAT VER · TƏSİR YARAT','Növbəti hədəfinizi tapın.','Təsdiqlənmiş proqramları araşdırın və təhlükəsizliyə töhfə verin.',`<button class="btn primary" data-action="${user?.role==='company'?'new-program':user?.role==='hacker'?'choose-report':'register'}">＋ ${user?.role==='company'?'Proqram yarat':user?.role==='hacker'?'Hesabat göndər':'İcmaya qoşul'}</button>`)+
  `<section class="welcome-band"><div><h2>Bacarıqlarınızla fərq yaradın.</h2><p>Əhatə dairəsini yoxlayın, zəiflikləri məsuliyyətlə bildirin və töhfənizə görə mükafat qazanın.</p></div></section>`+
  `<section class="metrics">${metric('Aktiv proqramlar',num(programs.length),'Təsdiqlənmiş hədəflər','programs')}${metric('Pul mükafatlı',num(programs.filter(p=>p.bounty_type==='cash').length),'Bug bounty proqramları','company')}${metric('Ən yüksək mükafat',highestRewards(programs),'Kritik tapıntılar üçün','leaderboard')}${metric('Reputasiya proqramları',num(programs.filter(p=>p.bounty_type==='points').length),'Təcrübənizi sübut edin','admin')}</section>`+
  `<div class="toolbar"><h2>Proqramları kəşf edin <span>${programs.length}</span></h2><div class="filters"><label class="sr-only" for="search">Proqram axtar</label><input class="search" id="search" type="search" placeholder="Proqram və ya şirkət axtar…" value="${esc(searchTerm)}"><label class="sr-only" for="bounty-filter">Mükafat növü</label><select id="bounty-filter"><option value="">Bütün mükafatlar</option value="cash">Pul mükafatı</option><option value="points">Reputasiya xalı</option></select></div></div><div id="program-grid" class="program-grid"></div><div class="helper-row">Hər proqramın əhatə dairəsi və qaydaları fərqlidir. Testə başlamazdan əvvəl onları oxuyun.</div>`;
  $('#bounty-filter').value=bountyFilter;drawCards();
}
function drawCards(){const rows=programs.filter(p=>(!bountyFilter||p.bounty_type===bountyFilter)&&`${p.title} ${p.company_name} ${p.industry}`.toLowerCase().includes(searchTerm.toLowerCase()));$('#program-grid').innerHTML=rows.length?rows.map((p,i)=>`<article class="program-card"><div class="card-top"><div class="company-mark tone-${i%4}">${publicImage(p.logo_url,'Şirkət loqosu','avatar-image')||raw(p.title.slice(0,1))}</div><div><h3>${raw(p.title)}</h3><div class="company-name">${raw(p.industry)}</div></div><span class="pill green">Aktiv</span></div><p class="card-desc">${raw(p.in_scope.split('\n').slice(-1)[0])}</p><div class="tags"><span class="tag">${raw(p.industry)}</span><span class="tag">${p.bounty_type==='cash'?'Bug bounty':'Reputasiya'}</span><span class="tag">Təsdiqlənib ✓</span></div><div class="card-bottom"><div><div class="reward-label">MÜKAFAT ARALIĞI</div><div class="reward">${num(p.reward_low)} – ${num(p.reward_critical)} <small>${p.bounty_type==='cash'?(currencyOf(p)==='AZN'?'₼':'USD'):'xal'}</small></div></div><button class="scope-link" data-action="scope" data-id="${p.id}">Ətraflı bax →</button></div></article>`).join(''):'<div class="empty"><strong>Proqram tapılmadı</strong><p>Proqramlar təsdiqləndikdə burada görünəcək. Axtarış filtrlərini də yoxlaya bilərsiniz.</p></div>';}
function renderLeaderboard(){
  $('#main').innerHTML=heading('BUGCASP İCMASI','Şərəf lövhəsi','Həll olunmuş tapıntılar. Ölçülə bilən töhfələr.')+`<div class="welcome-band"><div><h2>Təhlükəsizliyi gücləndirən tədqiqatçılar.</h2><p>Reputasiya xalları yalnız hesabat həll olunduqda verilir.</p></div><span class="band-tag">HALL OF FAME</span></div><div class="panel table-wrap"><table><thead><tr><th>SIRA</th><th>TƏDQİQATÇI</th><th>HƏLL OLUNMUŞ</th><th>REPUTASİYA</th></tr></thead><tbody>${leaderboard.length?leaderboard.map((u,i)=>`<tr><td><span class="rank ${i<3?'gold':''}">${String(i+1).padStart(2,'0')}</span></td><td><div class="name-cell"><span class="avatar">${publicImage(u.avatar_url,'Profil şəkli','avatar-image')||raw(u.username.slice(0,2).toUpperCase())}</span><div><strong>${raw(u.username)}</strong><p>${u.bio?raw(u.bio):'Təhlükəsizlik tədqiqatçısı'}</p></div></div></td><td>${num(u.resolved_bugs)} hesabat</td><td><strong>${num(u.reputation_score)}</strong> <small class="muted">xal</small></td></tr>`).join(''):'<tr><td colspan="4">İlk təsdiqlənmiş tədqiqatçıları gözləyirik.</td></tr>'}</tbody></table></div>`;
}
function reportsTable(){return `<div class="table-wrap"><table><thead><tr><th>HESABAT</th><th>PROQRAM</th><th>CİDDİLİK</th><th>STATUS</th><th></th></tr></thead><tbody>${reports.length?reports.map(r=>`<tr><td><small class="muted">BC-${r.id}</small><br><strong>${raw(r.title)}</strong></td><td>${raw(r.program_title)}</td><td>${pill(r.severity||'Qiymətləndirilməyib')}</td><td>${pill(r.status)}</td><td><button class="btn small" data-action="report-detail" data-id="${r.id}">Bax</button></td></tr>`).join(''):'<tr><td colspan="5">Hələ hesabat yoxdur.</td></tr>'}</tbody></table></div>`;}
function renderReports(){$('#main').innerHTML=heading('TƏDQİQATÇI MƏRKƏZİ','Hesabatlarım','Tapıntılarınızın baxış və həll prosesini izləyin.',`<button class="btn primary" data-action="choose-report">＋ Hesabat göndər</button>`)+`<section class="metrics">${metric('Bütün hesabatlar',reports.length,'Təqdim etdiyiniz tapıntılar','reports')}${metric('Baxışdadır',reports.filter(r=>['New','Triaged'].includes(r.status)).length,'Triage prosesi','admin')}${metric('Həll olunub',reports.filter(r=>r.status==='Resolved').length,'Təsdiqlənmiş töhfələr','programs')}${metric('Reputasiya',num(user.reputation_score),'Hesab üzrə ümumi xal','leaderboard')}</section><div class="panel">${reportsTable()}</div>`;}
function renderCompany(){$('#main').innerHTML=mediaEditor(true)+heading('ŞİRKƏT PORTALI','Təhlükəsizlik iş sahəsi','Proqramlarınızı və daxil olan hesabatları idarə edin.',companyProfile.is_approved?'<button class="btn primary" data-action="new-program">＋ Proqram yarat</button>':'')+(!companyProfile.is_approved?`<div class="notice warning">Şirkət statusu: ${esc(companyProfile.review_state)}. ${companyProfile.review_note?raw(companyProfile.review_note):'Proqram yaratmaq üçün platforma təsdiqi gözlənilir.'}</div>`:'')+`<section class="metrics">${metric('Proqramlar',programs.length,'Şirkətinizin proqramları','programs')}${metric('Yeni hesabatlar',reports.filter(r=>r.status==='New').length,'İlkin baxış gözləyir','reports')}${metric('Həll olunub',reports.filter(r=>r.status==='Resolved').length,'Bağlanmış tapıntılar','admin')}${metric('Ödənilmiş mükafat',paidTotals(reports),'Şirkət tərəfindən təsdiqlənib','leaderboard')}</section><div class="panel"><h2>Proqramlarım</h2><div class="table-wrap"><table><thead><tr><th>PROQRAM</th><th>TƏSDİQ</th><th>VƏZİYYƏT</th><th></th></tr></thead><tbody>${programs.length?programs.map(p=>`<tr><td><strong>${raw(p.title)}</strong>${p.review_note?'<p class="muted">'+raw(p.review_note)+'</p>':''}</td><td>${pill(p.review_state)}</td><td>${p.admin_suspended?'Admin dayandırıb':p.is_active?'Aktiv':'Dayandırılıb'}${p.suspension_reason?'<p class="muted">'+raw(p.suspension_reason)+'</p>':''}</td><td><button class="btn small" data-action="toggle-program" data-id="${p.id}" ${p.admin_suspended?'disabled':''}>${p.is_active?'Dayandır':'Aktiv et'}</button></td></tr>`).join(''):'<tr><td colspan="4">Hələ proqram yaradılmayıb.</td></tr>'}</tbody></table></div></div><div class="panel"><h2>Daxil olan hesabatlar</h2>${reportsTable()}</div>`;}
function renderAdmin(companies,pending,all,stats){$('#main').innerHTML=heading('PLATFORMA İDARƏETMƏSİ','Admin paneli','Müraciətləri yoxlayın, hesabatları izləyin və mübahisələri həll edin.')+adminMenu()+`<section class="metrics">${metric('Ümumi ödəniş',totalsText(stats.payouts_by_currency||{AZN:stats.total_payouts}),'Şirkətlərin qeydə aldığı ödənişlər','leaderboard')}${metric('Aktiv proqramlar',stats.active_programs,'Təsdiqlənmiş proqramlar','programs')}${metric('Açıq hesabatlar',stats.pending_reports,'New və Triaged','reports')}${metric('Tədqiqatçılar',stats.researchers,'E-poçtu təsdiqlənmiş','users')}</section><div class="panel"><h2>Şirkət təsdiqləri <span class="pill amber">${companies.length}</span></h2><div class="table-wrap"><table><thead><tr><th>ŞİRKƏT</th><th>SAHƏ</th><th>QƏRAR</th></tr></thead><tbody>${companies.length?companies.map(c=>`<tr><td><strong>${raw(c.company_name)}</strong><p class="muted">${raw(c.website_url)}</p></td><td>${raw(c.industry)}</td><td><div class="actions"><button class="btn primary small" data-action="approve-company" data-id="${c.id}">Təsdiqlə</button><button class="btn danger small" data-action="reject-company" data-id="${c.id}">Rədd et</button></div></td></tr>`).join(''):'<tr><td colspan="3">Gözləyən şirkət yoxdur.</td></tr>'}</tbody></table></div></div><div class="panel"><h2>Proqram təsdiqləri <span class="pill amber">${pending.length}</span></h2>${pending.map(p=>`<div class="notice"><strong>${raw(p.title)}</strong> · ${raw(p.company_name)}<p>${raw(p.target_url)}</p><p><b>Əhatə dairəsi:</b> ${raw(p.in_scope)}</p><p><b>İstisnalar:</b> ${raw(p.out_of_scope)}</p><p><b>Qaydalar:</b> ${raw(p.rules)}</p><p><b>Mükafat:</b> ${p.reward_low} / ${p.reward_medium} / ${p.reward_high} / ${p.reward_critical} ${p.bounty_type==='cash'?(currencyOf(p)==='AZN'?'AZN':'USD'):'xal'}</p><div class="actions"><button class="btn primary small" data-action="approve-program" data-id="${p.id}">Təsdiqlə</button><button class="btn danger small" data-action="reject-program" data-id="${p.id}">Rədd et</button></div></div>`).join('')||'<p class="muted">Gözləyən proqram yoxdur.</p>'}</div><div class="panel"><h2>Bütün hesabatlar</h2>${reportsTable()}</div><div class="panel"><h2>Ən fəal tədqiqatçılar</h2><div class="tags">${stats.top_researchers.map(u=>`<span class="tag">${raw(u.username)} · ${num(u.reputation_score)} xal</span>`).join('')||'Hələ məlumat yoxdur.'}</div></div>`;}

async function scope(id){const p=programs.find(p=>p.id===id)||(PREVIEW?demoPrograms.find(p=>p.id===id):await api('/hacker/programs/'+id));modal(p.title,`${publicImage(p.logo_url,'Şirkət loqosu')}<p class="muted">${raw(p.company_name)} · ${raw(p.industry)}</p><p class="mono">${raw(p.target_url)}</p><div class="reward-grid">${['Low','Medium','High','Critical'].map(s=>`<div class="reward-box"><span>${s}</span><strong>${p.bounty_type==='cash'?money(p['reward_'+s.toLowerCase()],currencyOf(p)):num(p['reward_'+s.toLowerCase()])+' xal'}</strong></div>`).join('')}</div><div class="section-label">ƏHATƏ DAİRƏSİ</div><div class="scope-content">${raw(p.in_scope)}</div><div class="section-label">ƏHATƏ DAİRƏSİNDƏN KƏNAR</div><div class="scope-content">${raw(p.out_of_scope)}</div><div class="section-label">ARAŞDIRMA QAYDALARI</div><div class="scope-content">${raw(p.rules)}</div><div class="form-actions"><button class="btn" data-action="close">Bağla</button><button class="btn primary" data-action="submit-form" data-id="${p.id}">Hesabat göndər</button></div>`,false);}
function authForm(mode='login'){
  const register=mode==='register';modal(register?'BugCasp-a qoşulun':'Hesabınıza daxil olun',`${PREVIEW?'<div class="notice">Bu, interfeys önizləməsidir. Burada real hesab yaradılmır.</div>':''}${register?`<div class="role-tabs"><button class="${authRole==='hacker'?'selected':''}" data-action="auth-role" data-role="hacker">Tədqiqatçı</button><button class="${authRole==='company'?'selected':''}" data-action="auth-role" data-role="company">Şirkət</button></div>`:''}<form id="auth-form" data-mode="${mode}"><div class="form-grid">${register?field('İstifadəçi adı','username','text','','required minlength="3" maxlength="40" pattern="[a-zA-Z0-9_-]+" autocomplete="username"'):''}${register?field('E-poçt ünvanı','email','email','','required autocomplete="email"'):field('İstifadəçi adı və ya e-poçt','identifier','text','','required autocomplete="username"')}${field('Şifrə','password','password','','required '+(register?'minlength="12" maxlength="72" autocomplete="new-password"':'autocomplete="current-password"'))}${register&&authRole==='company'?field('Şirkət adı','company_name','text','','required')+field('Fəaliyyət sahəsi','industry','text','','required')+field('Əsas sayt','website_url','url','','required placeholder="https://"'):''}${register&&authRole==='hacker'?area('Haqqınızda','bio','', 'maxlength="2000"')+field('GitHub profili','github','url')+field('TryHackMe profili','tryhackme','url')+field('Hack The Box profili','hackthebox','url'):''}</div>${register?'<p id="email-feedback" class="muted" style="font-size:12px;margin-top:12px">E-poçt domeni yoxlanılır, hesab məktubdakı keçidlə aktivləşir. Şifrə: ən azı 12 simvol.</p>':''}<div class="error" id="form-error" role="alert"></div><div class="form-actions"><button type="button" class="text-button" data-action="${register?'login':'register'}">${register?'Hesabım var':'Hesab yarat'}</button><button class="btn primary" type="submit">${register?'Qeydiyyatdan keç':'Daxil ol'}</button></div></form>${!register?'<button class="text-button" data-action="forgot-password">Şifrəni unutmuşam</button><button class="text-button" data-action="resend-form">Təsdiq məktubunu yenidən göndər</button>':''}`);
}
function forgotForm(){modal('Şifrənin bərpası',`<form id="forgot-password-form">${field('Hesabın e-poçtu','email','email','','required autocomplete="email"')}<p class="muted">Təsdiqlənmiş e-poçtunuza 30 dəqiqə etibarlı keçid göndəriləcək.</p><div id="form-error" class="error" role="alert"></div><div class="form-actions"><button class="btn primary" type="submit">Bərpa keçidi göndər</button></div></form>`);}
function resetForm(){modal('Yeni şifrə təyin et',`<form id="reset-password-form">${field('Yeni şifrə','new_password','password','','required minlength="12" maxlength="72" autocomplete="new-password"')}${field('Şifrəni təkrarla','confirm_password','password','','required minlength="12" maxlength="72" autocomplete="new-password"')}<p class="muted">Ən azı 12 simvol. Köhnə giriş sessiyaları bağlanacaq.</p><div id="form-error" class="error" role="alert"></div><div class="form-actions"><button class="btn primary" type="submit">Şifrəni yenilə</button><button class="text-button" type="button" data-action="forgot-password">Yeni keçid istə</button></div></form>`);}
async function verifyLink(token){if(PREVIEW)return toast('E-poçt təsdiqi tam tətbiqdə işləyir.');try{const result=await api('/auth/verify-email',{method:'POST',body:{token}});modal('E-poçt təsdiqləndi',`<p class="success">Hesabınız aktivləşdi. İndi daxil ola bilərsiniz.</p><p class="muted">Xoş gəldiniz məktubu: ${esc(result.welcome_email)}</p><div class="form-actions"><button class="btn primary" data-action="login">Daxil ol</button></div>`);}catch(e){modal('Təsdiq alınmadı',`<p class="error">${esc(e.message)}</p><button class="btn" data-action="resend-form">Yeni keçid istə</button>`);}}
async function submitForm(id){if(user?.role!=='hacker'){authForm('login');return;}if(!programs.length)programs=PREVIEW?demoPrograms:await api('/hacker/programs');if(!id){modal('Proqram seçin',programs.filter(p=>p.is_approved&&p.is_active).map(p=>`<button class="btn" data-action="submit-form" data-id="${p.id}">${raw(p.title)}</button>`).join('')||'<p>Aktiv proqram yoxdur.</p>');return;}selectedFile=null;modal('Zəiflik hesabatı',`<form id="report-form"><div class="form-grid"><input type="hidden" name="program_id" value="${Number(id)}">${field('Hesabat başlığı','title','text','','required minlength="5" maxlength="200"')}<div class="field"><label for="category">CWE / OWASP kateqoriyası</label><select id="category" name="cwe_category">${['CWE-79 · XSS','CWE-89 · SQLi','CWE-918 · SSRF','CWE-639 · IDOR','CWE-78 · RCE','CWE-287 · Authentication','CWE-200 · Information disclosure','Other'].map(x=>`<option value="${esc(x)}">${x}</option>`).join('')}</select></div></div><div class="section-label">SÜBUT FAYLI</div><div id="dropzone" class="dropzone"><strong id="file-label">PDF və ya TXT faylını buraya sürüşdürün</strong><p>Yalnız .pdf və .txt · maksimum 4 MB</p><label class="sr-only" for="evidence">Sübut faylı seç</label><input id="evidence" type="file" accept=".pdf,.txt"></div><p id="file-error" class="error" role="alert"></p><p class="muted">Təkrarlama addımlarını və təsiri sübut faylında izah edin.</p><div id="form-error" class="error" role="alert"></div><div class="form-actions"><button type="button" class="btn" data-action="close">Ləğv et</button><button class="btn primary" type="submit">Hesabatı göndər</button></div></form>`);wireDrop();}
function wireDrop(){const zone=$('#dropzone');zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');chooseFile(e.dataTransfer.files[0]);});$('#evidence').addEventListener('change',e=>chooseFile(e.target.files[0]));}
function chooseFile(file){selectedFile=null;$('#file-label').setAttribute('translate','yes');$('#file-error').textContent='';if(!file)return;const valid=/\.(pdf|txt)$/i.test(file.name)&&file.size>0&&file.size<=4*1024*1024;if(!valid){$('#file-error').textContent='Yalnız boş olmayan .pdf və .txt faylları qəbul edilir (maksimum 4 MB).';$('#evidence').value='';$('#file-label').textContent='PDF və ya TXT faylını buraya sürüşdürün';return;}selectedFile=file;$('#file-label').setAttribute('translate','no');$('#file-label').textContent=file.name+' · '+Math.ceil(file.size/1024)+' KB';}
function newProgram(){if(user?.role!=='company'){toast('Proqram yaratmaq üçün şirkət hesabı tələb olunur.');return;}modal('Yeni bug bounty proqramı',`<div class="program-logo-heading">${publicImage(companyProfile?.logo_url,'Şirkət loqosu','avatar-image')}<span>${raw(companyProfile?.company_name||user.username)}</span></div><p class="muted">Şirkət portalında yüklədiyiniz loqo proqramın başlığında görünür.</p><form id="program-form"><div class="step-track"><span id="step1" class="current">01 · Əsas məlumatlar</span><span>—</span><span id="step2">02 · Mükafat və qaydalar</span></div><div class="wizard-step" id="wizard-1"><div class="form-grid">${field('Proqram adı','title','text','','required minlength="4" maxlength="180"')}${field('Hədəf URL','target_url','url','','required placeholder="https://"')}${area('Əhatə dairəsindəki aktivlər','in_scope','','required minlength="5"')}${area('Əhatə dairəsindən kənar','out_of_scope','','required minlength="5"')}</div><div class="form-actions"><button class="btn primary" type="button" data-action="wizard-next">Davam et →</button></div></div><div class="wizard-step" id="wizard-2" hidden><div class="form-grid"><div class="field full"><label for="bounty-type">Mükafat növü</label><select name="bounty_type" id="bounty-type"><option value="cash">Pul mükafatı (AZN — manat)</option><option value="points">Reputasiya xalı</option></select></div>${['low','medium','high','critical'].map((s,i)=>field(s.toUpperCase()+' mükafatı','reward_'+s,'number',[50,150,500,1500][i],'required min="0" max="1000000"')).join('')}${area('Araşdırma qaydaları (RoE)','rules','','required minlength="10"')}</div><p class="notice" style="margin-top:18px">Proqram admin təsdiqindən sonra ictimai siyahıya əlavə olunacaq.</p><div class="form-actions"><button class="btn" type="button" data-action="wizard-back">Geri</button><button class="btn primary" type="submit">Təsdiqə göndər</button></div></div><div id="form-error" class="error" role="alert"></div></form>`);}
function reportDetail(id){const r=reports.find(x=>x.id===id);if(!r)return;modal('BC-'+r.id+' · Hesabat',`<h3>${raw(r.title)}</h3><div class="tags">${pill(r.status)}${pill(r.severity||'Qiymətləndirilməyib')}<span class="tag">${raw(r.cwe_category)}</span></div><p class="muted" style="font-size:13px;margin-top:12px">${raw(r.program_title)} · ${raw(r.hacker)}</p>${[['Təkrarlama addımları',r.poc_steps],['Təsir analizi',r.impact],['HTTP sorğu / cavab',r.http_payload],['Mübahisə',r.dispute],['Şirkətin izahı',r.reviewer_note],['Admin qeydi',r.mediation]].filter(([,v])=>v).map(([t,v])=>`<div class="report-block"><h3>${t}</h3><pre translate="no">${esc(v)}</pre></div>`).join('')}<div class="report-tools"><button class="btn" data-admin-action="messages" data-id="${id}">Müzakirə və izahlar</button>${user.role==='superadmin'&&r.dispute_open?`<button class="btn primary" data-admin-action="resolve-dispute" data-id="${id}">Mübahisəni bağla</button>`:''}</div>${r.attachment_path?`<button class="btn" data-action="view-file" data-id="${id}">▤ Sübut faylını aç</button>`:''}${r.reputation_awarded?`<p class="success">+${r.reputation_awarded} reputasiya xalı${r.cash_awarded?' · '+money(r.cash_awarded,currencyOf(r))+' '+(r.payout_paid?'ödənilib':'mükafat təsdiqlənib'):''}</p>`:''}${user.role!=='hacker'?`<form id="status-form" data-id="${id}"><div class="section-label">HESABATIN İDARƏ EDİLMƏSİ</div><div class="form-grid"><div class="field"><label for="report-status">Status</label><select name="status" id="report-status">${['New','Triaged','Resolved','Duplicate','Informative','Not Applicable'].map(s=>`<option value="${s}" ${s===r.status?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label for="report-severity">Təhlükə dərəcəsi</label><select id="report-severity" name="severity" ${r.reputation_awarded?'disabled':''}><option value="">Dərəcə seçin</option>${['Low','Medium','High','Critical'].map(s=>`<option value="${s}" ${r.severity===s?'selected':''}>${s}</option>`).join('')}</select></div>${area(user.role==='superadmin'?'Mediation qeydi':'Baxış qeydi','note','',user.role==='superadmin'?'required':'')}</div><div id="form-error" class="error" role="alert"></div><div class="form-actions">${user.role==='company'&&r.status==='Resolved'&&r.cash_awarded&&!r.payout_paid?`<button class="btn" type="button" data-action="mark-paid" data-id="${id}">Xarici ödənişi qeydə al</button>`:''}<button class="btn primary" type="submit">Statusu yenilə</button></div></form>`:`<div class="form-actions"><button class="btn" data-action="dispute-form" data-id="${id}">Admin baxışı istə</button></div>`}`);}
async function viewFile(id){const r=reports.find(x=>x.id===id);let url;if(PREVIEW){url=URL.createObjectURL(new Blob(['BUGCASP — NÜMUNƏ SÜBUT\n\nBu fayl yalnız interfeys nümayişi üçündür.\n'+r.poc_steps],{type:'text/plain'}));}else{const response=await fetch('/api/company/attachment/'+encodeURIComponent(r.attachment_path),{credentials:'same-origin'});if(!response.ok)throw new Error('Fayla giriş mümkün deyil.');const blob=await response.blob();url=URL.createObjectURL(blob);}modal('Sübut sənədi',`<iframe title="Sübut sənədinə baxış" class="document-frame" ${r.attachment_path.endsWith(".pdf")&&!PREVIEW?"":"sandbox"} src="${url}"></iframe><div class="form-actions"><a class="btn" href="${url}" download="evidence${r.attachment_path.endsWith('.pdf')?'.pdf':'.txt'}">Faylı endir</a><button class="btn" data-action="report-detail" data-id="${id}">Hesabata qayıt</button></div>`);$('#modal').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});}
async function approve(kind,id,approved){modal(approved?'Təsdiq qərarı':'Rədd qərarı',`<form id="approval-form" data-kind="${kind}" data-id="${id}" data-approved="${approved}"><p class="muted">${approved?'Müraciəti təsdiqləmək':'Müraciəti rədd etmək'} üçün qərarınızı qeydə alın.</p><div class="form-grid" style="margin-top:18px">${area('Qeyd','note','','required minlength="3" maxlength="2000"')}</div><div id="form-error" class="error" role="alert"></div><div class="form-actions"><button class="btn" type="button" data-action="close">Ləğv et</button><button class="btn primary" type="submit">Qərarı saxla</button></div></form>`);}

document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=Number(el.dataset.id);try{
  if(a==='forgot-password')forgotForm();if(a==='settings'){closeModal();location.hash='settings';}if(a==='close')closeModal();if(a==='retry')await render();if(a==='login'||a==='register')authForm(a);
  if(a==='join-researcher'||a==='join-company'){authRole=a==='join-company'?'company':'hacker';authForm('register');}
  if(a==='auth-role'){authRole=el.dataset.role;authForm('register');}
  if(a==='logout'){if(!PREVIEW)await api('/auth/logout',{method:'POST'});user=null;location.hash='home';await render();}
  if(a==='scope')await scope(id);if(a==='submit-form')await submitForm(id);if(a==='choose-report')await submitForm();if(a==='new-program')newProgram();if(a==='report-detail')reportDetail(id);if(a==='view-file')await viewFile(id);
  if(a==='wizard-next'){const inputs=[...$('#wizard-1').querySelectorAll('input,textarea')];if(inputs.every(x=>x.reportValidity())){$('#wizard-1').hidden=true;$('#wizard-2').hidden=false;$('#step1').classList.remove('current');$('#step2').classList.add('current');}}
  if(a==='wizard-back'){$('#wizard-1').hidden=false;$('#wizard-2').hidden=true;$('#step1').classList.add('current');$('#step2').classList.remove('current');}
  if(a==='toggle-program'){const p=programs.find(x=>x.id===id);if(PREVIEW)p.is_active=!p.is_active;else await api('/company/programs/'+id+'/active',{method:'PUT',body:{is_active:!p.is_active}});await render();toast('Proqramın vəziyyəti yeniləndi.');}
  if(a.startsWith('approve-')||a.startsWith('reject-'))await approve(a.split('-')[1],id,a.startsWith('approve'));
  if(a==='resend-form')modal('Təsdiq məktubunu yenidən göndər',`<form id="resend-form">${field('E-poçt','email','email','','required')}<div id="form-error" class="error" role="alert"></div><div class="form-actions"><button class="btn primary">Göndər</button></div></form>`);
  if(a==='dispute-form')modal('Admin baxışı istə',`<form id="dispute-form" data-id="${id}">${area('Mübahisənin səbəbi','note','','required minlength="10" maxlength="5000"')}<div id="form-error" class="error" role="alert"></div><div class="form-actions"><button class="btn primary">Adminə göndər</button></div></form>`);
  if(a==='mark-paid')modal('Ödənişi qeydə al',`<form id="paid-form" data-id="${id}"><p class="notice">Bu əməliyyat pul köçürmür. Yalnız ayrıca etdiyiniz ödənişi qeydə alır.</p><label style="display:flex;gap:10px;font-size:14px"><input type="checkbox" required style="width:18px">Tədqiqatçıya ödənişin edildiyini təsdiqləyirəm.</label><div id="form-error" class="error" role="alert"></div><div class="form-actions"><button class="btn primary">Ödənilmiş kimi işarələ</button></div></form>`);
}catch(e){toast(e.message);}});
document.addEventListener('input',e=>{if(e.target.name==='username'&&e.target.closest('#account-form')){clearTimeout(usernameCheckTimer);usernameCheckVersion++;e.target.setCustomValidity('');const feedback=$('#username-feedback');if(feedback)feedback.textContent='';const input=e.target;usernameCheckTimer=setTimeout(()=>checkUsername(input),450);}if(e.target.id==='search'){searchTerm=e.target.value;drawCards();}});
document.addEventListener('change',e=>{if(e.target.id==='bounty-filter'){bountyFilter=e.target.value;drawCards();}if(e.target.id==='demo-role'){setDemoUser(e.target.value);location.hash=user?.role==='company'?'company':user?.role==='superadmin'?'admin':user?'programs':'home';render();}});
document.addEventListener('focusout',async e=>{if(e.target.name==='email'&&$('#email-feedback')&&e.target.checkValidity()){const feedback=$('#email-feedback'),address=e.target.value;feedback.textContent='Poçt serveri yoxlanılır…';try{if(PREVIEW){feedback.textContent='Önizləmə: real DNS və e-poçt yoxlaması aparılmır.';return;}await api('/auth/check-email',{method:'POST',body:{email:address}});if(feedback.isConnected&&e.target.value===address)feedback.textContent='Poçt serveri tapıldı. Ünvan məktubdakı keçidlə təsdiqlənəcək.';}catch(err){if(feedback.isConnected)feedback.textContent=err.message;}}});
document.addEventListener('submit',async event=>{const form=event.target;if(!form.id||form.matches('[data-managed]'))return;event.preventDefault();const button=form.querySelector('button[type="submit"],button:not([type])');if(button)button.disabled=true;const data=Object.fromEntries(new FormData(form));const error=$('#form-error');if(error)error.textContent='';try{
  if(form.id==='forgot-password-form'){
    if(PREVIEW)throw new Error('Bərpa məktubu yalnız canlı saytda göndərilir.');
    const result=await api('/auth/forgot-password',{method:'POST',body:{email:data.email}});
    modal('E-poçtunuzu yoxlayın',`<p>${esc(result.message)}</p><button class="btn" data-action="login">Girişə qayıt</button>`);
  }
  if(form.id==='reset-password-form'){
    if(data.new_password!==data.confirm_password)throw new Error('Şifrələr uyğun gəlmir.');
    if(PREVIEW)throw new Error('Şifrə bərpası yalnız canlı saytda işləyir.');
    await api('/auth/reset-password',{method:'POST',body:{token:resetToken,new_password:data.new_password}});
    resetToken=null;user=null;await render();authForm('login');toast('Şifrəniz yeniləndi. Yeni şifrə ilə daxil olun.');
  }
  if(form.id==='account-form'){
    if(data.new_password!==data.confirm_password)throw new Error('Yeni şifrələr uyğun deyil.');
    const body={current_password:data.current_password,username:data.username};
    if(data.new_password)body.new_password=data.new_password;
    if(PREVIEW){toast('Önizləmə: hesab məlumatları dəyişdirilmir.');return;}
    const result=await api('/auth/account',{method:'PUT',body});user=result.user;await render();toast(result.message);
  }
  if(form.id==='profile-form'){if(PREVIEW){user={...user,...data};}else{const result=await api('/auth/profile',{method:'PUT',body:data});user=result.user;}await render();toast(PREVIEW?'Önizləmə: dəyişikliklər səhifə yenilənənədək saxlanılır.':'Profil yeniləndi.');}
  if(form.id==='auth-form'){
    if(PREVIEW){toast('Önizləmə: hesab yaradılmır. Yuxarıdakı rol seçicisini istifadə edin.');return;}
    if(form.dataset.mode==='login'){const result=await api('/auth/login',{method:'POST',body:data});user=result.user;closeModal();location.hash=user.role==='company'?'company':user.role==='superadmin'?'admin':'programs';await render();}
    else{const result=await api('/auth/register',{method:'POST',body:{...data,role:authRole}});modal('E-poçtunuzu təsdiqləyin',`<div class="notice">Qeydiyyat alındı. Hesab yalnız e-poçt təsdiqindən sonra aktivləşəcək.</div><p>${result.email_delivery==='sent'?'Təsdiq keçidi e-poçt ünvanınıza göndərildi.':result.email_delivery==='logged_locally'?'Yerli sınaq rejimi: məktub email-outbox.log faylına yazıldı. Real e-poçt göndərilmədi.':'Məktub göndərilmədi. Administrator e-poçt xidmətinin sazlamalarını tamamladıqdan sonra yenidən göndərməyi yoxlayın.'}</p><div class="form-actions"><button class="btn" data-action="resend-form">Yenidən göndər</button><button class="btn primary" data-action="login">Girişə qayıt</button></div>`);}
  }
  if(form.id==='resend-form'){if(!PREVIEW)await api('/auth/resend-verification',{method:'POST',body:data});closeModal();toast(PREVIEW?'Önizləmə: məktub göndərilmir.':'Hesab gözləmədədirsə, yeni məktub tələb edildi.');}
  if(form.id==='report-form'){
    if(!selectedFile)throw new Error('Sübut faylını əlavə edin.');
    if(PREVIEW){const p=demoPrograms.find(p=>p.id===Number(data.program_id));demoReports.unshift({...seedReports[0],...data,id:Date.now(),program_id:p.id,program_title:p.title,severity:null,severity_reviewed:false,status:'New',attachment_path:'sample.txt',reputation_awarded:0});}
    else{const body=new FormData(form);if(selectedFile)body.append('attachment',selectedFile);await api('/hacker/reports',{method:'POST',body});}
    closeModal();location.hash='reports';await render();toast(PREVIEW?'Nümunə hesabat əlavə edildi; səhifə yenilənəndə silinəcək.':'Hesabat göndərildi.');
  }
  if(form.id==='program-form'){for(const k of ['reward_low','reward_medium','reward_high','reward_critical'])data[k]=Number(data[k]);if(PREVIEW){demoPending.push({...data,id:Date.now(),company_name:'Caspian Digital',is_active:true,is_approved:false,review_state:'pending'});}else await api('/company/programs',{method:'POST',body:data});closeModal();await render();toast('Proqram təsdiq üçün göndərildi.');}
  if(form.id==='status-form'){if(!data.severity)delete data.severity;const id=Number(form.dataset.id);if(PREVIEW){const r=demoReports.find(x=>x.id===id);if(['Triaged','Resolved'].includes(data.status)&&!data.severity&&!r.severity)throw new Error('Təhlükə dərəcəsini seçin.');if(data.severity)r.severity=data.severity;r.status=data.status;if(user.role==='superadmin')r.mediation=data.note;if(data.status==='Resolved'&&!r.reputation_awarded){const p=demoPrograms.find(p=>p.id===r.program_id);const reward=p['reward_'+r.severity.toLowerCase()];r.reputation_awarded=p.bounty_type==='cash'?{Low:50,Medium:150,High:400,Critical:800}[r.severity]:Math.max(1,reward);r.cash_awarded=p.bounty_type==='cash'?reward:0;}}else await api('/'+(user.role==='superadmin'?'admin':'company')+'/reports/'+id+'/status',{method:'PUT',body:data});closeModal();await render();toast('Hesabat statusu yeniləndi.');}
  if(form.id==='approval-form'){const id=Number(form.dataset.id),kind=form.dataset.kind,approved=form.dataset.approved==='true';if(PREVIEW){if(kind==='company')demoCompanies=demoCompanies.filter(c=>c.id!==id);else{const p=demoPending.find(p=>p.id===id);if(approved){p.is_approved=true;p.review_state='approved';demoPrograms.push(p);}demoPending=demoPending.filter(p=>p.id!==id);}}else await api('/admin/approve-'+kind+'/'+id,{method:'POST',body:{approved,note:data.note}});closeModal();await render();toast('Qərar saxlanıldı.');}
  if(form.id==='dispute-form'){const id=Number(form.dataset.id);if(PREVIEW)demoReports.find(r=>r.id===id).dispute=data.note;else await api('/hacker/reports/'+id+'/dispute',{method:'POST',body:data});closeModal();await render();toast('Admin baxışı tələb edildi.');}
  if(form.id==='paid-form'){const id=Number(form.dataset.id);if(PREVIEW)demoReports.find(r=>r.id===id).payout_paid=true;else await api('/company/reports/'+id+'/mark-paid',{method:'POST'});closeModal();await render();toast('Xarici ödəniş qeydə alındı.');}
}catch(e){if(error?.isConnected)error.textContent=e.message;else toast(e.message);}finally{if(button?.isConnected)button.disabled=false;}});
window.addEventListener('hashchange',render);
async function boot(){try{$('#year').textContent=new Date().getFullYear();if(PREVIEW){$('#preview-notice').hidden=false;setDemoUser('hacker');}else{try{user=await api('/auth/me');}catch{user=null;}}await render();loadAnnouncements();}finally{$('.app-shell').hidden=false;$('#startup-screen').hidden=true;}}
boot();
